import sys

def main():
    s = sys.stdin.readline().strip()
    stack = []
    pairs = {')': '(', ']': '[', '>': '<'}
    openings = set(pairs.values())

    for c in s:
        if c in openings:
            stack.append(c)
        else:
            if not stack or stack[-1] != pairs[c]:
                print("No")
                return
            stack.pop()

    print("Yes" if not stack else "No")

